insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"the_alphabet_adventure_q01_acorn_teaching","locale":"he","line_order":0,"content":"A היא אות מיוחדת: היא יכולה לייצג כמה צלילים.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_acorn_teaching","locale":"he","line_order":1,"content":"Acorn פירושו בלוט.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_acorn_teaching","locale":"he","line_order":2,"content":"בתחילת acorn היא מייצגת /eɪ/, כמו בשם האות.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_acorn_teaching","locale":"he","line_order":3,"content":"Apple ו-acorn מתחילות באותה אות, אף שהצלילים שונים.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_acorn_teaching","locale":"he","line_order":4,"content":"האזן לשתי הדוגמאות; לא צריך לכתוב אותיות שעוד לא למדת.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_acorn_teaching","locale":"he","line_order":5,"content":"אל תמתח את הקול כדי ליצור צליל אחר. מדובר בשני צלילים שונים, ולא רק בהבדל באורך.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_apple_teaching","locale":"he","line_order":0,"content":"Apple פירושו תפוח. A היא אות תנועה. באנגלית אותיות התנועה העיקריות הן A, E, I, O ו-U.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_apple_teaching","locale":"he","line_order":1,"content":"אלה אותיות של האלף-בית, והן שונות מסימני הניקוד בעברית.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_apple_teaching","locale":"he","line_order":2,"content":"בתחילת apple האות מייצגת את הצליל /æ/. העברית אינה מייצגת את הצליל הזה במדויק, ולכן נקשיב להקלטה באנגלית.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_apple_teaching","locale":"he","line_order":3,"content":"האזן למילה השלמה ובחר את האות של הצליל הראשון. אין צורך לקרוא את המילה כולה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_apple_teaching","locale":"he","line_order":4,"content":"יש שתי אפשרויות. את האות שלנו כבר הכרנו; הסימן האחר הוא רק אפשרות נוספת.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_finish","locale":"he","line_order":0,"content":"תפוח!","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_finish","locale":"he","line_order":1,"content":"עכשיו אני נזכר שלקחתי תפוח כשיצאתי מהבקתה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_finish","locale":"he","line_order":2,"content":"יש ברמז הבא ציור של התיק שלי.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_finish","locale":"he","line_order":3,"content":"אולי הוא יזכיר לי מה קרה אחר כך.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_form_teaching","locale":"he","line_order":0,"content":"נתחיל באות A.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_form_teaching","locale":"he","line_order":1,"content":"קוראים לה איי.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_form_teaching","locale":"he","line_order":2,"content":"לכתוב אותה אפשר בשתי צורות: A גדולה ו-a קטנה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_form_teaching","locale":"he","line_order":3,"content":"זאת אותה אות.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_form_teaching","locale":"he","line_order":4,"content":"השם של האות והצליל שהיא מייצגת אינם תמיד אותו הדבר.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_start","locale":"he","line_order":0,"content":"בדיוק אותך הייתי צריך.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_start","locale":"he","line_order":1,"content":"אני אורן, ואני אוהב לספר סיפורים בחגיגות הממלכה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_start","locale":"he","line_order":2,"content":"הערב אספר סיפור בחגיגת הממלכה, אבל הספר שלי נעול בתיבה ושכחתי איפה המפתח.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_start","locale":"he","line_order":3,"content":"כתבתי לעצמי רמזים, וחלק מהאותיות נמחקו.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_start","locale":"he","line_order":4,"content":"ברמז הראשון מצויר תפוח.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_start","locale":"he","line_order":5,"content":"תוכל לעזור לי לפענח אותו?","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_start","locale":"he","line_order":6,"content":"גש למאיה כדי ללמוד. את התרגולים תבצע בשולחן הלימוד שבפארק.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_word_teaching","locale":"he","line_order":0,"content":"עכשיו צייר את המילה תפוח באנגלית לפי הדוגמה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_word_teaching","locale":"he","line_order":1,"content":"האותיות האחרות עדיין חדשות, ולכן הן מופיעות בשבילך.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q01_word_teaching","locale":"he","line_order":2,"content":"הציור עוזר להכיר צורות; הוא לא דורש לקרוא את כל המילה לבד.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_blending","locale":"he","line_order":0,"content":"אחרי הזיהוי נחבר את הצליל של b לצליל /æ/ של a.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_blending","locale":"he","line_order":1,"content":"/b/ ואז /æ/.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_blending","locale":"he","line_order":2,"content":"זה תרגול של חיבור צלילים, ולא מילה שנדרש לקרוא.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_blending","locale":"he","line_order":3,"content":"בסוף bag יש אות שעוד לא למדנו; היא כבר כתובה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_blending","locale":"he","line_order":4,"content":"צריך להשלים רק את האות הראשונה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_finish","locale":"he","line_order":0,"content":"נכון, לקחתי את התיק.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_finish","locale":"he","line_order":1,"content":"התפוח היה בפנים, אבל שמעתי ממנו רחש מוזר.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_finish","locale":"he","line_order":2,"content":"ברמז הבא מצויר מי שהתחבא בו.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_form_teaching","locale":"he","line_order":0,"content":"ברמז הבא מופיע תיק.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_form_teaching","locale":"he","line_order":1,"content":"Bag פירושו תיק.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_form_teaching","locale":"he","line_order":2,"content":"נלמד את B, שנקראת בי.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_form_teaching","locale":"he","line_order":3,"content":"B היא הצורה הגדולה ו-b הקטנה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_form_teaching","locale":"he","line_order":4,"content":"בתחילת bag האות מייצגת /b/.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_form_teaching","locale":"he","line_order":5,"content":"בחיבור צלילים משתמשים בצליל הזה, ולא בשם בי.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_start","locale":"he","line_order":0,"content":"ברמז הבא מצויר התיק הישן שלי. הוא היה כבד מהרגיל, וגם השמיע רחש.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q02_start","locale":"he","line_order":1,"content":"גש למאיה כדי ללמוד. את התרגולים תבצע בשולחן הלימוד שבפארק. אולי הרמז יזכיר לי מה היה בתיק.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_blending","locale":"he","line_order":0,"content":"עכשיו נחבר /k/ ואחריו /æ/.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_blending","locale":"he","line_order":1,"content":"חיבור צלילים נעשה לפי הסדר.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_blending","locale":"he","line_order":2,"content":"במילה חתול נשלים רק את האות הראשונה; הסוף כבר כתוב כי עוד לא למדנו את כולו.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_blending","locale":"he","line_order":3,"content":"בתרגול הבא נחזור גם על האות של תיק.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_finish","locale":"he","line_order":0,"content":"החתול שלי!","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_finish","locale":"he","line_order":1,"content":"הוא התחבא בתיק, וכשפתחתי אותו הוא קפץ החוצה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_finish","locale":"he","line_order":2,"content":"החזקתי את המפתח באותו רגע.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_finish","locale":"he","line_order":3,"content":"הרמז האחרון הוא הכתובת שעל הכרית שקיבלתי מהבת שלי.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_form_teaching","locale":"he","line_order":0,"content":"ברמז מצויר חתול.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_form_teaching","locale":"he","line_order":1,"content":"Cat פירושו חתול.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_form_teaching","locale":"he","line_order":2,"content":"האות החדשה היא C, שנקראת סי.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_form_teaching","locale":"he","line_order":3,"content":"C גדולה ו-c קטנה הן אותה אות.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_form_teaching","locale":"he","line_order":4,"content":"בתחילת cat היא מייצגת /k/.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_form_teaching","locale":"he","line_order":5,"content":"לאות הזאת יש גם צלילים אחרים, אבל היום נשתמש בדוגמה של החתול.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_start","locale":"he","line_order":0,"content":"ברמז הבא מצויר חתול. עכשיו אני מתחיל להבין מאיפה בא הרחש.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q03_start","locale":"he","line_order":1,"content":"גש למאיה כדי ללמוד את האות החדשה. את התרגולים תבצע בשולחן הלימוד שבפארק.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_finish","locale":"he","line_order":0,"content":"Dad, אבא!","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_finish","locale":"he","line_order":1,"content":"הבת שלי רקמה את המילה על הכרית שלי ליד החלון.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_finish","locale":"he","line_order":2,"content":"כשהחתול קפץ, הנחתי שם את המפתח והרמתי אותו בשתי הידיים.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_finish","locale":"he","line_order":3,"content":"עכשיו נזכרתי איפה לחפש.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_finish","locale":"he","line_order":4,"content":"מצאתי את המפתח ופתחתי את התיבה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_finish","locale":"he","line_order":5,"content":"הספר בפנים, ובחגיגה אוכל לספר איך עזרת לי.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_finish","locale":"he","line_order":6,"content":"אותיות הן כמו מפתחות קטנים לסיפורים.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_finish","locale":"he","line_order":7,"content":"אני נותן לך 5 מטבעות על העזרה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_finish","locale":"he","line_order":8,"content":"מאיה הכינה לך עוד שלושה תרגולים קצרים לשיעורי הבית.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_form_teaching","locale":"he","line_order":0,"content":"האות החדשה היא D, שנקראת די.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_form_teaching","locale":"he","line_order":1,"content":"D היא גדולה ו-d קטנה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_form_teaching","locale":"he","line_order":2,"content":"בתחילת dog, שפירושה כלב, היא מייצגת /d/.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_form_teaching","locale":"he","line_order":3,"content":"השם די שונה מהצליל /d/.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_form_teaching","locale":"he","line_order":4,"content":"שים לב: ל-b יש קו גבוה משמאל לבטן, ול-d יש קו גבוה מימין לבטן.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_form_teaching","locale":"he","line_order":5,"content":"אלה שתי אותיות שונות.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_full_words","locale":"he","line_order":0,"content":"כבר למדנו את כל האותיות של dad.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_full_words","locale":"he","line_order":1,"content":"Dad פירושו אבא.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_full_words","locale":"he","line_order":2,"content":"נחבר לפי הסדר /d/, /æ/, /d/.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_full_words","locale":"he","line_order":3,"content":"יש d גם בתחילת המילה וגם בסופה.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_full_words","locale":"he","line_order":4,"content":"עכשיו bad: /b/, /æ/, /d/.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_full_words","locale":"he","line_order":5,"content":"Bad פירושו רע.","line_format":"plain_text"},{"dialogue_key":"the_alphabet_adventure_q04_full_words","locale":"he","line_order":6,"content":"אם נחליף את האות הראשונה, נשנה גם את הצליל הראשון ואת המשמעות."